bsl_m=; if [ -r /usr/lib/breadstick/bsl-os.sh ] && . /usr/lib/breadstick/bsl-os.sh && command -v bsl_pkg_mark >/dev/null 2>&1 && command -v bsl_pkg_also >/dev/null 2>&1 && bsl_pkg_mark install; then bsl_m=1; fi
( [ -z "$bsl_m" ] || bsl_pkg_also $$
set -e
true
{ if [ -r /usr/lib/breadstick/bsl-os.sh ]; then n=$(. /usr/lib/breadstick/bsl-os.sh && bsl_pkg_names mpv audacity | tr '\n' ' ') || n='mpv audacity'; else n='mpv audacity'; fi; s=0; T=; if [ -z "${n# }" ]; then s=1; echo '[BSL] This Linux instance has no package for this; nothing was installed.' >&2; elif [ -e /var/lib/pacman/db.lck ]; then s=1; echo '[BSL] Another package operation is running or was interrupted; nothing was installed or upgraded.' >&2; elif ! { T=$(mktemp -d) && chmod 755 "$T" && mkdir -p "$T/db/sync" && ln -s /var/lib/pacman/local "$T/db/local"; }; then s=1; else cp -p /var/lib/pacman/sync/*.db* "$T/db/sync/" 2>/dev/null || true; if ! pacman -Sy --dbpath "$T/db" --logfile /dev/null >/dev/null; then s=1; echo '[BSL] The package databases could not be refreshed; nothing was installed or upgraded.' >&2; elif ! pacman -Sup --needed --dbpath "$T/db" --logfile /dev/null $n >/dev/null; then s=1; echo '[BSL] pacman cannot install this from the repositories of this Linux instance; nothing was installed or upgraded.' >&2; else c=0; for f in "$T"/db/sync/*.db*; do if [ -f "$f" ]; then cp -p "$f" /var/lib/pacman/sync/ || c=1; fi; done; if [ $c = 0 ]; then if [ -r /usr/lib/breadstick/bsl-os.sh ] && (. /usr/lib/breadstick/bsl-os.sh && command -v bsl_pkg_run >/dev/null 2>&1); then (. /usr/lib/breadstick/bsl-os.sh && bsl_pkg_run install pacman -Su --needed --noconfirm $n); else pacman -Su --needed --noconfirm $n; fi || s=$?; else s=1; fi; fi; fi; if [ -n "$T" ]; then rm -f "$T/db/local" "$T/db/db.lck" "$T"/db/sync/*; rmdir "$T/db/sync" "$T/db" "$T" 2>/dev/null || true; fi; (exit $s); }
fc-cache -f >/dev/null 2>&1 || true
echo 'Installed.'
); bsl_rc=$?; [ -z "$bsl_m" ] || bsl_pkg_unmark $bsl_rc; exit $bsl_rc
